mapper.select:
${pagingTop} SELECT homepage_id, popup_idx, popup_name, html, html_use_yn, popup_type, link_url, use_yn, print_seq, width, height, x_position, y_position, org_file_name, server_file_name, file_extension, file_size, add_date, link_target, TO_CHAR(start_date, 'yyyy-MM-dd') AS start_date, TO_CHAR(end_date, 'yyyy-MM-dd') AS end_date, common_yn, alt_text, link_type FROM CMS_POPUP WHERE homepage_id = #{homepage_id}
AND ${search_type} LIKE '%'||#{search_text}||'%'
AND link_target = #{link_target}
AND use_yn = #{use_yn}
ORDER BY print_seq ASC, add_date DESC ${pagingBottom}

SELECT
	COUNT(*)
FROM
	CMS_POPUP
WHERE
	homepage_id = #{homepage_id}

AND	${search_type} LIKE '%'||#{search_text}||'%'


AND	link_target = #{link_target}


AND	use_yn = #{use_yn}

mapper.insert:
SELECT NVL(MAX(popup_idx),0)+1 FROM CMS_POPUP WHERE homepage_id = #{homepage_id}
INSERT INTO CMS_POPUP ( homepage_id, popup_idx, popup_name, html, html_use_yn, popup_type, link_url, use_yn, print_seq, width, height, x_position, y_position, add_id, add_date, link_target, start_date, end_date, common_yn, alt_text, link_type
, org_file_name, server_file_name, file_extension, file_size
) VALUES ( #{homepage_id}, #{popup_idx}, #{popup_name}, #{html}, #{html_use_yn}, #{popup_type}, #{link_url}, #{use_yn}, #{print_seq}, #{width}, #{height}, #{x_position}, #{y_position}, #{add_id}, SYSDATE, #{link_target}, #{start_date}, #{end_date}, #{common_yn}, #{alt_text}, #{link_type}
, #{org_file_name}, #{server_file_name}, #{file_extension}, #{file_size}
)

mapper.update:
UPDATE CMS_POPUP SET popup_name = #{popup_name}, html = #{html}, html_use_yn = #{html_use_yn}, popup_type = #{popup_type}, link_url = #{link_url}, link_type = #{link_type}, use_yn = #{use_yn}, print_seq = #{print_seq}, width = #{width}, height = #{height}, x_position = #{x_position}, y_position = #{y_position}, link_target = #{link_target}, start_date = #{start_date}, end_date = #{end_date}, common_yn = #{common_yn},
org_file_name = #{org_file_name}, server_file_name = #{server_file_name}, file_extension = #{file_extension}, file_size = #{file_size},
alt_text = #{alt_text}, modify_id = #{modify_id}, modify_date = SYSDATE WHERE homepage_id = #{homepage_id} AND popup_idx = #{popup_idx}

mapper.delete:
DELETE FROM
	CMS_POPUP
WHERE
	homepage_id = #{homepage_id}
AND	popup_idx = #{popup_idx}
